// Renders emoji as Apple emoji images (public/emoji/*.webp, generated by scripts/build-emoji.mjs)
// so they look like iOS everywhere – Windows/Android previews and PNG exports included.
import { Fragment } from 'react';
import names from '../emojiMap.json';

const FILES = new Map<string, string>();
for (const n of names as string[]) FILES.set(n.split('-').filter((c) => c !== 'fe0f').join('-'), n);

const RE =
  /(\p{Regional_Indicator}\p{Regional_Indicator}|[#*0-9]️?⃣|\p{Extended_Pictographic}(?:️|\p{Emoji_Modifier})?(?:‍\p{Extended_Pictographic}(?:️|\p{Emoji_Modifier})?)*)/u;
const SPLIT = new RegExp(RE.source, 'gu');

export function emojiFile(e: string) {
  const key = [...e]
    .map((c) => c.codePointAt(0)!.toString(16))
    .filter((c) => c !== 'fe0f')
    .join('-');
  return FILES.get(key) ?? FILES.get(key.replace(/-200d.*/, '')) ?? null;
}

export function Emo({ text }: { text: string | null | undefined }) {
  if (!text) return null;
  if (!RE.test(text)) return <>{text}</>;
  const parts = text.split(SPLIT);
  return (
    <>
      {parts.map((p, i) => {
        if (i % 2 === 0) return p ? <Fragment key={i}>{p}</Fragment> : null;
        const file = emojiFile(p);
        return file ? (
          <img key={i} src={`emoji/${file}.webp`} alt={p} draggable={false} className="apple-emoji" />
        ) : (
          <Fragment key={i}>{p}</Fragment>
        );
      })}
    </>
  );
}
